var poCache=null,poSel={};
function irPO(){
  pararCamera();$('faixaPO').textContent='PREÇOS OFF-LINE · '+quem;mostrar('tPO');
  try{poCache=JSON.parse(localStorage.getItem('ci_po')||'null');}catch(e){}
  poSel={};renderPO();carregarPO();
}
function carregarPO(){
  api({acao:'precosOff',quem:quem}).then(function(r){if(r&&r.ok){poCache={itens:r.itens||[],em:r.arquivoEm||'',verTudo:!!r.verTudo};try{localStorage.setItem('ci_po',JSON.stringify(poCache));}catch(e){}renderPO();}else if(r&&r.erro){toast(r.erro,'err');}}).catch(function(){});
}
function renderPO(){
  var box=$('poLista');box.innerHTML='';
  if(!poCache){box.innerHTML='<p class="dica">Carregando…</p>';return;}
  var its=poCache.itens;
  var pend=its.filter(function(i){return !i.status;}),conf=its.filter(function(i){return i.status==='CONFIRMADO';}),ativ=its.filter(function(i){return i.status==='ATIVADO';});
  $('poProg').textContent=pend.length+(pend.length===1?' para etiquetar':' para etiquetar');
  $('poArq').textContent=poCache.em?'Relatório da Nath atualizado em '+poCache.em:'';
  if(!its.length){box.innerHTML='<p class="dica" style="font-size:16px;margin-top:20px">Nenhum preço off-line no relatório. 👍</p>';}
  // pendentes agrupados por repositora (as minhas primeiro) e local
  var grupos={},ordem=[];
  pend.forEach(function(i){var g=i.rep||'SEM RESPONSÁVEL';if(!grupos[g]){grupos[g]=[];ordem.push(g);}grupos[g].push(i);});
  ordem.sort(function(a,b){var ma=ehMeu(a)?0:1,mb=ehMeu(b)?0:1;if(ma!==mb)return ma-mb;if(a==='SEM RESPONSÁVEL')return 1;if(b==='SEM RESPONSÁVEL')return -1;return a<b?-1:1;});
  ordem.forEach(function(g){
    var lst=grupos[g].sort(function(a,b){return (a.local+a.desc)<(b.local+b.desc)?-1:1;});
    var hd=document.createElement('div');hd.className='grp';hd.textContent=(ehMeu(g)?'MEUS · ':'')+g.toUpperCase()+' ('+lst.length+')';box.appendChild(hd);
    var ul=document.createElement('ul');ul.className='po';
    lst.forEach(function(it){
      var li=document.createElement('li');if(poSel[it.sku])li.className='sel';
      var sobe=it.novo>it.atual;
      li.innerHTML='<span class="ck">'+(poSel[it.sku]?'✓':'')+'</span><div class="tx"><div class="d">'+esc(it.desc)+'</div><div class="m">SKU '+esc(it.sku)+(it.local?' · '+esc(it.local):(it.cat?' · '+esc(it.cat):''))+'</div>'
        +'<div class="pr"><b>'+brl(it.novo)+'</b> <span class="'+(sobe?'up':'dn')+'">'+(sobe?'▲':'▼')+'</span> <s>'+brl(it.atual)+'</s></div></div>';
      li.onclick=function(){vibra();if(poSel[it.sku])delete poSel[it.sku];else poSel[it.sku]=1;renderPO();};
      ul.appendChild(li);
    });
    box.appendChild(ul);
  });
  [['AGUARDANDO ATIVAÇÃO',conf,'conf'],['PREÇO JÁ ATIVADO',ativ,'ativ']].forEach(function(o){
    if(!o[1].length)return;
    var hd=document.createElement('div');hd.className='grp';hd.textContent=o[0]+' ('+o[1].length+')';box.appendChild(hd);
    var ul=document.createElement('ul');ul.className='po';
    o[1].forEach(function(it){
      var li=document.createElement('li');li.className=o[2];
      li.innerHTML='<span class="ck">'+(o[2]==='ativ'?'✅':'⏳')+'</span><div class="tx"><div class="d">'+esc(it.desc)+'</div><div class="m">'+brl(it.novo)+' · '+esc(it.quem)+' '+esc(it.em)+(it.ativ?' · ativado '+esc(it.ativ):'')+'</div>'
        +(o[2]==='conf'?'<button class="des">desfazer</button>':'')+'</div>';
      var d=li.querySelector('.des');if(d)d.onclick=function(ev){ev.stopPropagation();desfazerPO(it,d);};
      ul.appendChild(li);
    });
    box.appendChild(ul);
  });
  var n=Object.keys(poSel).length,bt=$('poBt');
  bt.style.display=n?'block':'none';bt.disabled=false;bt.textContent='🏷️ COLOQUEI A ETIQUETA — PODE ATIVAR ('+n+')';
}
function confirmarPO(){
  var skus=Object.keys(poSel);if(!skus.length)return;
  var bt=$('poBt');bt.disabled=true;bt.textContent='Enviando…';
  api({acao:'confirmarPrecosOff',quem:quem,token:token,skus:skus}).then(function(r){
    if(r&&r.ok){vibra();poCache.itens.forEach(function(i){if(poSel[i.sku]&&!i.status){i.status='CONFIRMADO';i.quem=quem;i.em='agora';}});poSel={};try{localStorage.setItem('ci_po',JSON.stringify(poCache));}catch(e){}toast('Enviado ✅ O preço será ativado no sistema');renderPO();return;}
    bt.disabled=false;renderPO();if(r&&r.reauth){irPin();return;}toast((r&&r.erro)||'Não enviou','err');
  }).catch(function(){bt.disabled=false;renderPO();toast('Sem conexão. Tente de novo.','err');});
}
function desfazerPO(it,b){
  b.disabled=true;b.textContent='…';
  api({acao:'desfazerPrecoOff',quem:quem,token:token,sku:it.sku,novo:it.novo}).then(function(r){
    if(r&&r.ok){it.status='';it.quem='';it.em='';renderPO();return;}
    b.disabled=false;b.textContent='desfazer';if(r&&r.reauth){irPin();return;}toast((r&&r.erro)||'Não desfez','err');
  }).catch(function(){b.disabled=false;b.textContent='desfazer';toast('Sem conexão. Tente de novo.','err');});
}

